import type { Question, QuestionTopic } from "@/lib/content/types";

import { SAMPLE_BASE } from "./shared";

/**
 * Five of the nine canonical search seeds from PRD 02 §6, used as the question
 * corpus so Ask and Search have something real to match against.
 *
 * These are seeded as `pending`, not `answered`. PRD 06 §3 asks for at least
 * one Verified question in the desk strip, and that is knowingly unmet: an
 * official answer is a factual claim and the Verified mark is the product's
 * trust signal, so neither can be generated by a build step. `/ask` renders
 * these truthfully as "Awaiting editor", which PRD 02 §3.2 already specifies.
 *
 * Consequence to expect: Home's "From the desk" strip and the Verified mark
 * stay empty until an editor answers. Swap `questionStatus`, `officialAnswer`,
 * `answeredAt`, and `sample` together when that happens.
 */
type QuestionSeed = {
  readonly slug: string;
  readonly title: string;
  readonly topic: QuestionTopic;
};

const QUESTION_SEEDS: readonly QuestionSeed[] = [
  {
    slug: "can-i-drink-tap-water-in-seoul",
    title: "Can I drink tap water in Seoul?",
    topic: "survival",
  },
  {
    slug: "apple-pay-on-a-seoul-bus",
    title: "Apple Pay on a Seoul bus",
    topic: "transit",
  },
  { slug: "esim-vs-sim-at-icn", title: "eSIM vs SIM at ICN", topic: "money" },
  {
    slug: "naver-map-vs-google-maps",
    title: "Naver Map vs Google Maps",
    topic: "transit",
  },
  {
    slug: "table-for-one-refused",
    title: "Table for one refused",
    topic: "etiquette",
  },
];

export const SEED_QUESTIONS: readonly Question[] = QUESTION_SEEDS.map(
  (seed) => ({
    ...SAMPLE_BASE,
    id: `question-${seed.slug}`,
    slug: seed.slug,
    title: seed.title,
    body: null,
    topic: seed.topic,
    neighborhoodSlug: null,
    askerName: "Real Korea desk",
    // Desk-seeded, so there is no visitor email to hold in the first place.
    askerEmail: null,
    questionStatus: "pending",
    officialAnswer: null,
    answerVerified: false,
    answeredAt: null,
    promotedToSlug: null,
    comments: [],
  }),
);
